let describe = global.get('describe', 'memoryOnly') || {};
if (typeof describe !== 'object') {
    describe = {};
}
if (typeof describe.pages !== 'object') {
    describe.pages = {};
}

// Set default app values
describe.app = {
    'title': 'DKNR',
    'version' : '0.0',
    'git': ''
}

// Set common pages rights
describe.pages['home'] = {
    'id': 'ba855b55e831d2b6',
    'name': 'home',
    'level': {
        'admin': true,
        'parent': true,
        'child': true,
        'visitor': true
    }
};
describe.pages['room'] = {
    'id': 'be3da16eb83104f6',
    'name': 'room',
    'level': {
        'admin': true,
        'parent': true,
        'child': true,
        'visitor': false
    }
};
